 1| /**
 2|  * RFC 9457 problem details. Every error response of this API is a Problem sent
 3|  * with `Content-Type: application/problem+json`.
 4|  */
 5| import type { Response } from 'express';
 6| import { z } from 'zod';
 7| 
 8| export const PROBLEM_TYPE_BASE = 'https://api.sf/problems/';
 9| export const PROBLEM_CONTENT_TYPE = 'application/problem+json';
10| 
11| export const ProblemSchema = z.object({
12|   type: z.url(),
13|   title: z.string().min(1),
14|   status: z.number().int().min(400).max(599),
15|   detail: z.string(),
16|   instance: z.string(),
17| });
18| export type Problem = z.infer<typeof ProblemSchema>;
19| 
20| /** What a thrower supplies; `instance` is filled in by the error middleware from the request. */
21| export const ProblemInitSchema = ProblemSchema.omit({ instance: true });
22| export type ProblemInit = z.infer<typeof ProblemInitSchema>;
23| 
24| /** The problem `type` URI for a slug, e.g. typeUri('not-found'). */
25| export function typeUri(slug: string): string {
26|   return `${PROBLEM_TYPE_BASE}${slug}`;
27| }
28| 
29| /** Throw this from a handler (or middleware); the error middleware turns it into a Problem response. */
30| export class HttpProblem extends Error {
31|   readonly type: string;
32|   readonly title: string;
33|   readonly status: number;
34|   readonly detail: string;
35| 
36|   constructor(init: ProblemInit) {
37|     super(init.detail);
38|     this.name = 'HttpProblem';
39|     this.type = init.type;
40|     this.title = init.title;
41|     this.status = init.status;
42|     this.detail = init.detail;
43|   }
44| 
45|   toProblem(instance: string): Problem {
46|     return ProblemSchema.parse({ type: this.type, title: this.title, status: this.status, detail: this.detail, instance });
47|   }
48| }
49| 
50| export function badRequest(detail: string, slug = 'malformed-json'): HttpProblem {
51|   return new HttpProblem({ type: typeUri(slug), title: 'Bad Request', status: 400, detail });
52| }
53| 
54| export function notFound(detail: string, slug = 'not-found'): HttpProblem {
55|   return new HttpProblem({ type: typeUri(slug), title: 'Not Found', status: 404, detail });
56| }
57| 
58| export function conflict(detail: string, slug = 'conflict'): HttpProblem {
59|   return new HttpProblem({ type: typeUri(slug), title: 'Conflict', status: 409, detail });
60| }
61| 
62| export function unprocessable(detail: string, slug = 'validation'): HttpProblem {
63|   return new HttpProblem({ type: typeUri(slug), title: 'Unprocessable Content', status: 422, detail });
64| }
65| 
66| export function internalError(detail = 'An unexpected error occurred.'): HttpProblem {
67|   return new HttpProblem({ type: typeUri('internal'), title: 'Internal Server Error', status: 500, detail });
68| }
69| 
70| export function sendProblem(res: Response, problem: Problem): void {
71|   res.status(problem.status).type(PROBLEM_CONTENT_TYPE).json(ProblemSchema.parse(problem));
72| }

